CREATE TABLE plume.assessment_template_drafts (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    workspace_id bigint NOT NULL REFERENCES plume.workspaces(id) ON DELETE CASCADE,
    template_key text NOT NULL,
    title text NOT NULL,
    kind text NOT NULL CHECK(kind IN ('pia','cross_border','ai','business_change')),
    revision bigint NOT NULL DEFAULT 1,
    created_by bigint NOT NULL REFERENCES plume.users(id),
    base_revision_id bigint REFERENCES plume.check_templates(id),
    published_revision_id bigint REFERENCES plume.check_templates(id),
    questions jsonb NOT NULL CHECK(jsonb_typeof(questions)='array'),
    state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','disabled')),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE(workspace_id,template_key)
);
CREATE TABLE plume.assessment_template_revisions (
    revision_id bigint PRIMARY KEY REFERENCES plume.check_templates(id),
    workspace_id bigint REFERENCES plume.workspaces(id) ON DELETE CASCADE,
    kind text NOT NULL CHECK(kind IN ('pia','cross_border','ai','business_change')),
    questions jsonb NOT NULL CHECK(jsonb_typeof(questions)='array'),
    disabled_at timestamptz
);
CREATE TABLE plume.assessments (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    workspace_id bigint NOT NULL REFERENCES plume.workspaces(id) ON DELETE CASCADE,
    activity_id bigint NOT NULL REFERENCES plume.activities(id) ON DELETE CASCADE,
    template_revision_id bigint NOT NULL REFERENCES plume.assessment_template_revisions(revision_id),
    creator_id bigint NOT NULL REFERENCES plume.users(id),
    kind text NOT NULL CHECK(kind IN ('pia','cross_border','ai','business_change')),
    title text NOT NULL,
    status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','needs_work','approved')),
    revision bigint NOT NULL DEFAULT 1,
    activity_snapshot jsonb NOT NULL,
    activity_digest text NOT NULL,
    facts jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(facts)='array'),
    facts_digest text NOT NULL,
    answers jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(answers)='array'),
    editor_ids bigint[] NOT NULL DEFAULT '{}',
    check_ids bigint[] NOT NULL DEFAULT '{}',
    facts_refreshed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    refresh_minutes integer NOT NULL DEFAULT 1440 CHECK(refresh_minutes BETWEEN 5 AND 43200),
    next_refresh_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '1 day',
    due_at timestamptz NOT NULL,
    stale boolean NOT NULL DEFAULT false,
    reassessment_pending boolean NOT NULL DEFAULT false,
    reviewer_id bigint REFERENCES plume.users(id),
    review_note text NOT NULL DEFAULT '',
    frozen_report jsonb,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE(workspace_id,id)
);
CREATE INDEX assessments_workspace_idx ON plume.assessments(workspace_id,id DESC);
CREATE INDEX assessments_refresh_idx ON plume.assessments(next_refresh_at,id);
CREATE TABLE plume.assessment_events (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    assessment_id bigint NOT NULL REFERENCES plume.assessments(id) ON DELETE CASCADE,
    actor_id bigint REFERENCES plume.users(id),
    action text NOT NULL,
    note text NOT NULL DEFAULT '',
    snapshot jsonb,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE plume.assessment_reassessment_tasks (
    assessment_id bigint PRIMARY KEY REFERENCES plume.assessments(id) ON DELETE CASCADE,
    reason text NOT NULL,
    state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','resolved')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    resolved_at timestamptz
);

INSERT INTO plume.check_templates(template_key,title,kind,version) VALUES('assessment-pia','个人信息保护影响评估','sharing',1);
INSERT INTO plume.assessment_template_revisions(revision_id,kind,questions) SELECT id,'pia','[{"key":"applicable","title":"是否触发个人信息保护影响评估","kind":"single","basis":"个人信息保护法第55条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"敏感个人信息、个人信息自动化决策、委托或向其他处理者提供、公开、出境及其他重大影响活动。","evidence":"实际个人信息范围、处理角色和触发条件说明。","acceptance":"适用结论有证据。条件未知时继续补充业务事实。","requirementCode":"P04","obligation":"conditional_law","required":true,"options":["yes","no","unknown"]},{"key":"purpose","title":"处理目的与必要性","kind":"text","basis":"个人信息保护法第6、13、55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"处理个人信息且触发影响评估的情形。","evidence":"活动目的、处理依据及最小范围说明。","acceptance":"处理目的具体，已核对适用依据，说明范围必要性。","requirementCode":"P04","obligation":"conditional_law","required":true,"factKey":"activity_purpose"},{"key":"processing_scope","title":"处理范围与接收角色","kind":"text","basis":"个人信息保护法第17、55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"处理个人信息且触发影响评估的情形。","evidence":"数据类型、主体、系统、接收方及委托或独立处理角色。","acceptance":"数据范围与实际处理活动、系统及接收关系一致。","requirementCode":"P04","obligation":"conditional_law","required":true},{"key":"subject_count","title":"去重个人信息主体数量","kind":"number","basis":"个人信息保护法第56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"规模是风险评估要素，出境路径还需按专门规定统计。","evidence":"统计时间、去重口径、来源与覆盖范围。","acceptance":"数量和统计口径可追溯，有限格式样本数量不替代主体数量。","requirementCode":"P04","obligation":"conditional_law","required":false},{"key":"impact","title":"个人权益影响与风险","kind":"text","basis":"个人信息保护法第56条第（二）项","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"存在对个人权益的影响或安全风险时。","evidence":"风险场景、受影响权益、范围和风险评估。","acceptance":"风险分析覆盖实际处理活动及潜在影响。","requirementCode":"P04","obligation":"conditional_law","required":true},{"key":"controls","title":"保护措施与有效性","kind":"text","basis":"个人信息保护法第56条第（三）项","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"评估范围内的数据处理活动。","evidence":"访问、加密、保留、撤权和权利响应等适用措施及测试。","acceptance":"保护措施合法、有效，与风险相适应，残余风险有明确处置。","requirementCode":"P04","obligation":"conditional_law","required":true},{"key":"evidence","title":"评估与处理记录证据","kind":"evidence","basis":"个人信息保护法第55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"依法需事前影响评估的情形。","evidence":"事前评估、审批及处理记录的已登记证据引用。","acceptance":"可核实评估早于处理，评估报告和处理记录至少保存三年。","requirementCode":"P04","obligation":"conditional_law","required":true}]'::jsonb FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-pia' AND version=1;
