INSERT INTO plume.check_templates(template_key,title,kind,version) VALUES('assessment-cross-border','数据出境专项评估','cross_border',1);
INSERT INTO plume.assessment_template_revisions(revision_id,kind,questions) SELECT id,'cross_border','[{"key":"applicable","title":"是否实际向境外提供数据","kind":"single","basis":"促进和规范数据跨境流动规定第2至10条","basisUrl":"https://www.cac.gov.cn/2024-03/22/c_1712776611775634.htm","applicability":"传输境外或境外主体能够访问、查询、下载境内数据的活动。","evidence":"实际链路、境外接收方、地域、访问与传输配置。","acceptance":"基于实际数据流确认范围，未确定的流向标为未知。","requirementCode":"T03","obligation":"conditional_law","required":true,"options":["yes","no","unknown"]},{"key":"recipient","title":"境外接收方与处理条件","kind":"text","basis":"个人信息保护法第38、39条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"向境外提供个人信息。","evidence":"接收方信息、目的、方式、类型、保护安排及适用告知同意记录。","acceptance":"接收方、目的、范围和保护安排与实际数据流一致。","requirementCode":"T03","obligation":"conditional_law","required":true,"factKey":"activity_recipient"},{"key":"factors","title":"出境路径判断所需条件","kind":"multi","basis":"促进和规范数据跨境流动规定第2至10条","basisUrl":"https://www.cac.gov.cn/2024-03/22/c_1712776611775634.htm","applicability":"已确认的数据出境活动。","evidence":"关基身份、重要数据认定、当年累计去重人数、敏感个人信息及适用例外的证明。","acceptance":"逐项记录已核条件和未知项，按完整条件选路径。","requirementCode":"T03","obligation":"conditional_law","required":true,"options":["cii","important_data","personal","sensitive_personal","exception_claimed","unknown"]},{"key":"subject_count","title":"当年累计出境个人信息主体数量","kind":"number","basis":"促进和规范数据跨境流动规定第7、8条","basisUrl":"https://www.cac.gov.cn/2024-03/22/c_1712776611775634.htm","applicability":"按当年1月1日起累计统计并结合规定的适用例外。","evidence":"普通与敏感信息主体分开统计的口径和证明。","acceptance":"主体数已去重，统计时间明确，敏感主体另附证据。","requirementCode":"T03","obligation":"conditional_law","required":true},{"key":"path","title":"出境合规路径及理由","kind":"single","basis":"促进和规范数据跨境流动规定第2至10条","basisUrl":"https://www.cac.gov.cn/2024-03/22/c_1712776611775634.htm","applicability":"已核实关基、数据类别、规模及例外等条件后。","evidence":"安全评估、标准合同、认证或适用例外的有效证明及依据。","acceptance":"路径前提可核实，材料与实际接收方和处理范围一致。","requirementCode":"T03","obligation":"conditional_law","required":true,"options":["security_assessment","standard_contract","certification","exception","unknown"]},{"key":"impact","title":"出境个人信息影响评估与风险","kind":"text","basis":"个人信息保护法第55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"向境外提供个人信息时。","evidence":"事前评估范围、合法性必要性、个人权益风险、措施和保留安排。","acceptance":"适用时评估早于处理，风险和措施覆盖真实链路。","requirementCode":"P04","obligation":"conditional_law","required":true},{"key":"evidence","title":"出境评审及复测证据","kind":"evidence","basis":"个人信息保护法第38、55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"所选合规路径和数据处理范围适用时。","evidence":"评审、批准路径、合同或认证、适用例外证明、整改复测。","acceptance":"证据支持路径结论，未解决差异进入现有整改流程。","requirementCode":"T03","obligation":"conditional_law","required":true}]'::jsonb FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-cross-border' AND version=1;
