INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'evidence',7,'出境评审及复测证据','T03','所选合规路径和数据处理范围适用时。','评审、批准路径、合同或认证、适用例外证明、整改复测。','证据支持路径结论，未解决差异进入现有整改流程。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-cross-border' AND version=1;
INSERT INTO plume.check_templates(template_key,title,kind,version) VALUES('assessment-ai','AI使用专项评估','ai',1);
INSERT INTO plume.assessment_template_revisions(revision_id,kind,questions) SELECT id,'ai','[{"key":"applicable","title":"活动是否涉及AI使用","kind":"single","basis":"企业AI使用治理建议","basisUrl":"https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm","applicability":"组织使用AI模型、知识库或工具处理数据的活动。","evidence":"模型与应用清单、使用角色和数据流。","acceptance":"记录实际使用范围，未知用途继续补证。","requirementCode":"X01","obligation":"recommended","required":true,"options":["yes","no","unknown"]},{"key":"public_service","title":"是否面向境内公众提供生成式AI服务","kind":"single","basis":"生成式人工智能服务管理暂行办法第2条","basisUrl":"https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm","applicability":"该办法以面向境内公众提供生成式AI服务为适用条件。","evidence":"访问对象、发布范围和服务方式。","acceptance":"内部研发使用与公众服务的适用事实已确认。","requirementCode":"X01","obligation":"conditional_law","required":true,"options":["yes","no","unknown"]},{"key":"data_sources","title":"输入和训练数据类别及来源","kind":"multi","basis":"生成式人工智能服务管理暂行办法第7、11条","basisUrl":"https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm","applicability":"公众服务按该办法执行，其他处理活动核对适用数据与个保要求。","evidence":"训练、输入、输出、检索及工具调用范围与来源授权。","acceptance":"来源和使用依据可追溯，个人信息、商业数据及来源不明数据已分别核查。","requirementCode":"X01","obligation":"conditional_law","required":true,"options":["business","personal","sensitive_personal","public","unknown"]},{"key":"provider_terms","title":"供应商留存、训练使用和部署地域","kind":"text","basis":"企业AI供应商治理建议","basisUrl":"https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm","applicability":"外部模型API或第三方托管可以接触数据的活动。","evidence":"供应商条款版本、实际设置、留存训练范围、处理地域。","acceptance":"条款、租户配置与批准范围一致，出境及委托处理另行核验。","requirementCode":"X01","obligation":"recommended","required":true},{"key":"pia_triggers","title":"AI场景影响评估触发条件","kind":"multi","basis":"个人信息保护法第55条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"敏感个人信息、个人信息自动化决策或向其他处理者提供等情形。","evidence":"模型实际用途、个人信息类别、接收角色和决策影响。","acceptance":"依据具体处理活动判断触发，使用AI本身不单独推定。","requirementCode":"P04","obligation":"conditional_law","required":true,"options":["sensitive_personal","automated_decision","providing","outbound","none","unknown"]},{"key":"controls","title":"AI输入、知识库与工具权限控制","kind":"text","basis":"企业AI权限治理建议","basisUrl":"https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm","applicability":"模型能够读取或操作组织数据的活动。","evidence":"已批准权限、脱敏策略、日志引用与合成测试。","acceptance":"授权和受限输入、检索及工具调用均有适用测试与残余风险处置。","requirementCode":"G03","obligation":"recommended","required":true},{"key":"evidence","title":"AI适用性与控制证据","kind":"evidence","basis":"个人信息保护法第55、56条及适用AI规则","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"按已确认的实际处理活动和服务范围。","evidence":"适用性、供应商评审、需要时的影响评估与控制验证记录。","acceptance":"证据覆盖适用义务及组织选定措施，未核实事实保持未知。","requirementCode":"X01","obligation":"conditional_law","required":true}]'::jsonb FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-ai' AND version=1;
INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'applicable',1,'活动是否涉及AI使用','X01','组织使用AI模型、知识库或工具处理数据的活动。','模型与应用清单、使用角色和数据流。','记录实际使用范围，未知用途继续补证。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-ai' AND version=1;
