INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'pia_triggers',5,'AI场景影响评估触发条件','P04','敏感个人信息、个人信息自动化决策或向其他处理者提供等情形。','模型实际用途、个人信息类别、接收角色和决策影响。','依据具体处理活动判断触发，使用AI本身不单独推定。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-ai' AND version=1;
INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'controls',6,'AI输入、知识库与工具权限控制','G03','模型能够读取或操作组织数据的活动。','已批准权限、脱敏策略、日志引用与合成测试。','授权和受限输入、检索及工具调用均有适用测试与残余风险处置。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-ai' AND version=1;
INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'evidence',7,'AI适用性与控制证据','X01','按已确认的实际处理活动和服务范围。','适用性、供应商评审、需要时的影响评估与控制验证记录。','证据覆盖适用义务及组织选定措施，未核实事实保持未知。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-ai' AND version=1;
INSERT INTO plume.check_templates(template_key,title,kind,version) VALUES('assessment-business-change','业务变更重评','sharing',1);
INSERT INTO plume.assessment_template_revisions(revision_id,kind,questions) SELECT id,'business_change','[{"key":"applicable","title":"是否存在数据处理业务变更","kind":"single","basis":"企业业务变更治理建议","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"业务、系统、目的、接收方、地域或控制变化的活动。","evidence":"变更单、前后范围和负责人确认。","acceptance":"变更事实和受影响处理活动可追溯。","requirementCode":"G01","obligation":"recommended","required":true,"options":["yes","no","unknown"]},{"key":"change_types","title":"变更涉及哪些处理条件","kind":"multi","basis":"个人信息保护法第14、17、55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"个人信息处理目的、方式、种类等变化时按适用义务核对。","evidence":"原活动版本与变更后的目的、方式、数据类型、接收方及地域。","acceptance":"前后差异已明确，告知、同意和事前评估按具体条件重核。","requirementCode":"P01","obligation":"conditional_law","required":true,"options":["purpose","method","data_types","recipient","region","access","model","unknown"]},{"key":"impact","title":"变更风险与评估触发判断","kind":"text","basis":"个人信息保护法第55、56条","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"变更后存在依法需影响评估的处理情形。","evidence":"新增风险、影响对象、原评估适用性与重评范围。","acceptance":"重评范围与变化一致，未确认事实明确列出。","requirementCode":"P04","obligation":"conditional_law","required":true},{"key":"approval","title":"业务变更审批与实施窗口","kind":"text","basis":"企业业务变更治理建议","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"组织实施数据处理变更。","evidence":"责任人、审批、实施及回退安排。","acceptance":"实施范围与批准一致，相关岗位责任明确。","requirementCode":"G01","obligation":"recommended","required":true},{"key":"controls","title":"变更后控制与复测","kind":"text","basis":"企业业务变更治理建议","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"权限、路径、模型或系统配置变化。","evidence":"同一合成用例、前后权限和路径证据、整改及复测。","acceptance":"控制验证覆盖变更边界，未通过项关联整改检查。","requirementCode":"G03","obligation":"recommended","required":true},{"key":"evidence","title":"变更与重评证据","kind":"evidence","basis":"按适用法定义务及组织变更制度","basisUrl":"https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm","applicability":"已确认的业务变更和处理范围。","evidence":"活动版本、审批和适用时的告知、授权、重评及复测记录。","acceptance":"证据可还原变更和决策过程，原版评估可追溯。","requirementCode":"G01","obligation":"recommended","required":true}]'::jsonb FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-business-change' AND version=1;
INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'applicable',1,'是否存在数据处理业务变更','G01','业务、系统、目的、接收方、地域或控制变化的活动。','变更单、前后范围和负责人确认。','变更事实和受影响处理活动可追溯。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-business-change' AND version=1;
