INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'impact',3,'变更风险与评估触发判断','P04','变更后存在依法需影响评估的处理情形。','新增风险、影响对象、原评估适用性与重评范围。','重评范围与变化一致，未确认事实明确列出。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-business-change' AND version=1;
