INSERT INTO plume.check_template_items(template_revision_id,item_key,position,title,requirement_code,applicability,evidence_requirements,acceptance_criteria) SELECT id,'evidence',6,'变更与重评证据','G01','已确认的业务变更和处理范围。','活动版本、审批和适用时的告知、授权、重评及复测记录。','证据可还原变更和决策过程，原版评估可追溯。' FROM plume.check_templates WHERE workspace_id IS NULL AND template_key='assessment-business-change' AND version=1;
